contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address logger, bool status) public payable {
        require(logger != address(0));
        bool before = c.approvedToLog(logger);
        bool ret = c.setApprovedLogger(logger, status);
        bool after = c.approvedToLog(logger);
        assert(after == status);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address logger) public payable {
        bool ret = c.approvedToLog(logger);
        bool direct = c.approvedLoggers(logger);
        assert(ret == direct);
    }
}
